// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address ownerAddr) public {
        vm.assume(ownerAddr != address(0));

        vm.prank(address(0));
        c.transferOwnership(ownerAddr);

        vm.prank(ownerAddr);
        bool success;
        try c.owned() {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}
